def canopy(radius=1000, rise=500, t=12, cap_d=312, cap_h=18):
    levels = [(radius, 0), (850, 180), (700, 300), (450, 420), (cap_d / 2, 488), (0.5, rise)]
    outer = s3d.loft("canopy", *[s3d.at(s3d.polygon(n=8, d=r * 2), z=z) for r, z in levels])
    inner = s3d.loft("inside", *[s3d.at(s3d.polygon(n=8, d=r * 2), z=z-t) for r, z in levels])
    skin = s3d.cut(outer, inner)
    s3d.material(skin, "fabric", color="#738dff")
    cap = s3d.at(s3d.dome("cap", d=cap_d, h=cap_h), z=rise-cap_h/2)
    s3d.material(cap, "plastic", color="#8d8d8d")
    return s3d.group("canopy_group", skin, cap)


