    s3d.joint("handle_pivot", handle, g, kind="revolute", axis="+Y", range=(-10.313, 37.242))
    return s3d.assembly("garden_gate", fence, gate, handle)

import sand3d as s3d
import numpy as np
import random

def young_teak_cluster(seed=0):
    s3d.facets(4, smooth=False)
    ground = earth_patch(seed=seed + 1)
    moss = continuous_moss_carpet(ground, seed=seed + 2)
    main = main_teak(seed=seed + 100)
    left = s3d.at(left_teak(seed=seed + 200), x=-4100, y=-1800, rz=116)
    rear = s3d.at(rear_teak(seed=seed + 300), x=3900, y=2100, rz=-53)
    return s3d.assembly('young_teak_cluster', ground, moss, main, left, rear)

def earth_patch(seed=1, radius=7900, depth_ratio=0.8, h=350, irregularity=450):
    sites = s3d.ring(11, radius).jitter(x=irregularity, y=irregularity, seed=seed)
    outline = s3d.poly([(f.origin.x, f.origin.y * depth_ratio) for f in sites])
    earth = s3d.extrude('earth_patch', outline, h)
    s3d.material(earth, 'soil', color='#66503a', roughness=1)
    return earth

def continuous_moss_carpet(earth, seed=2, thickness=170, relief=115, cushion=1700, mesh_step=950):
    moss = s3d.scale(s3d.copy(earth), (1, 1, thickness / 350))
    moss = s3d.at(moss, z=350)
    s3d.displace(moss, relief, cushion, direction='+Z', faces='top', step=mesh_step, noise=lambda x, y, z: s3d.noise(x / cushion, y / cushion, z * 0, seed=seed))

    def moss_color(x, y, z):
        patches = s3d.noise(x / (cushion * 2), y / (cushion * 2), z * 0, seed=seed + 1)
        return np.where((patches > 0)[:, None], [0.32, 0.43, 0.12], [0.27, 0.37, 0.1])
    s3d.material(moss, 'moss', color=moss_color, roughness=1)
    return moss

def main_teak(seed=100, h=13800, lean=430, base=480):
    path = trunk_axis(h, lean)
    trunk = main_teak_trunk(path, seed=seed + 1)
    twigs, leaf_sites = main_teak_twigs(path, h, seed=seed + 2)
    leaves = main_teak_paired_leaves(path, leaf_sites, seed=seed + 3)
    return s3d.at(s3d.group('main_teak', trunk, twigs, leaves), x=-450, y=600, z=base)

def trunk_axis(h, lean):
    return s3d.spline([(0, 0, 0), (lean * 0.2, 0, h * 0.35), (lean * 0.65, lean * 0.12, h * 0.72), (lean, lean * 0.2, h)])

def main_teak_trunk(path, seed=101, diameter=315):
    return teak_trunk(path, diameter, seed)

def teak_trunk(path, diameter, seed):
    trunk = s3d.wire('tapered_teak_trunk', path, d=[(0, diameter * 1.5), (0.035, diameter), (0.5, diameter * 0.66), (0.85, diameter * 0.32), (1, diameter * 0.12)])
    rng = random.Random(seed)
    s3d.material(trunk, 'bark', color=rng.choice(['#91623e', '#986846', '#8b5c3b']), roughness=1)
    return trunk

def main_teak_twigs(path, h, seed=102):
    return twig_crown(path, h, seed=seed, branch_ratio=0.125)

def twig_crown(path, h, seed, branch_ratio, tiers=3, inclination=61):
    rng = random.Random(seed)
    nodes = s3d.along(path, count=tiers, span=(0.49, 0.84), spin=90)
    lengths = s3d.vary(h * branch_ratio, h * branch_ratio * 0.18, tiers * 2, seed=seed + 1)
    twigs = []
    leaf_sites = []
    for i, node in enumerate(nodes):
        for side in range(2):
            length = lengths[i * 2 + side] * (1 - i * 0.12)
            axis = s3d.spline([(0, 0, 0), (length * 0.03, 0, length * 0.55), (length * 0.12, 0, length)])
            frame = node.turn(rz=side * 180 + rng.uniform(-13, 13), ry=inclination + rng.uniform(-7, 7))
            twig = s3d.at(teak_twig(axis, h * 0.005, seed + 10 + i * 2 + side), on=frame)
            twigs.append(twig)
            for j, f in enumerate(s3d.along(axis, count=2, span=(0.38, 0.88))):
                for opposite in range(2):
                    local_site = f.turn(rz=90 + opposite * 180 + rng.uniform(-12, 12), ry=68 + rng.uniform(-9, 9))
                    leaf_sites.append((frame, local_site, j == 1, 1 - i * 0.09))
    return (s3d.group('open_paired_twigs', *twigs), leaf_sites)

def teak_twig(path, diameter, seed):
    twig = s3d.wire('short_twig', path, d=[(0, diameter), (1, diameter * 0.22)])
    s3d.material(twig, 'bark', color='#9d744b', roughness=1)
    return twig

def main_teak_paired_leaves(path, sites, seed=103):
    return paired_leaf_crown(path, sites, seed=seed, length=1950)

def paired_leaf_crown(path, sites, seed, length):
    rng = random.Random(seed)
    leaves = []
    for k, (parent, site, new, size) in enumerate(sites):
        leaf = teak_leaf(length * size * rng.uniform(0.83, 1.12) * (0.85 if new else 1), new, seed + 20 + k)
        leaves.append(s3d.at(s3d.group('attached_pair_blade', s3d.at(leaf, on=site)), on=parent))
    terminal = s3d.along(path, count=3, span=(0.87, 0.99), spin=90)
    for k, site in enumerate(terminal):
        for opposite in range(2):
            orient = site.turn(rz=opposite * 180 + 25, ry=68 + rng.uniform(-8, 8)).turn(rz=90)
            leaf = teak_leaf(length * (0.78 - k * 0.19), k > 0, seed + 100 + k * 2 + opposite)
            leaves.append(s3d.at(leaf, on=orient))
    return s3d.group('opposite_broad_teak_leaves', *leaves)

def teak_leaf(length, new, seed, width_ratio=0.62, petiole_ratio=0.12, fold_ratio=0.065):
    rng = random.Random(seed)
    width = length * width_ratio * rng.uniform(0.9, 1.08)
    stalk = length * petiole_ratio
    fold = width * fold_ratio
    droop = length * 0.13
    stations = [(0, 0, 0), (0.2, 0.68, 0.1), (0.46, 1, 0.3), (0.7, 0.83, 0.58), (0.88, 0.44, 0.85), (1, 0, 1)]
    blade = s3d.loft('broad_pointed_blade', *[s3d.station(z=stalk + u * length, w=w * width, d=w * fold, y=-curve * droop) for u, w, curve in stations], tip='sharp')
    greens = ['#78aa38', '#88b646', '#95bc4d'] if new else ['#397b32', '#448b35', '#559338', '#4e8734']
    s3d.material(blade, 'leaf', color=rng.choice(greens), roughness=0.88)
    rib = s3d.loft('prominent_central_vein', *[s3d.station(z=stalk + u * length, w=width * 0.026 * (1 - u * 0.9), d=width * 0.026 * (1 - u * 0.9), y=-fold * 0.5 * w - curve * droop) for u, w, curve in stations])
    s3d.material(rib, 'leaf', color='#b3c66a' if new else '#8eaf50', roughness=0.9)
    petiole = s3d.wire('short_petiole', [(0, 0, 0), (0, 0, stalk)], d=width * 0.032)
    s3d.material(petiole, 'leaf', color='#819c43', roughness=0.95)
    return s3d.group('teak_leaf', petiole, blade, rib)

def left_teak(seed=200, h=10200, lean=490, base=480):
    path = trunk_axis(h, lean)
    trunk = left_teak_trunk(path, seed=seed + 1)
    twigs, leaf_sites = left_teak_twigs(path, h, seed=seed + 2)
    leaves = left_teak_paired_leaves(path, leaf_sites, seed=seed + 3)
    return s3d.at(s3d.group('left_teak', trunk, twigs, leaves), z=base)

def left_teak_trunk(path, seed=201, diameter=240):
