import sand3d as s3d
import random
import math
import numpy as np

def mountain_mushroom_boulder(seed=0):
    soil = bare_soil_patch(seed=seed + 1)
    rock = mountain_boulder(seed=seed + 2)
    fractures = exposed_fracture_planes(rock, seed=seed + 3)
    lower = lower_mushroom_cluster(rock, seed=seed + 4)
    side = side_mushroom_cluster(rock, seed=seed + 5)
    upper = upper_mushroom_cluster(rock, seed=seed + 6)
    moss = crevice_moss(rock, seed=seed + 7)
    gravel = scattered_angular_gravel(soil, rock, seed=seed + 8)
    vignette = s3d.assembly('mountain_mushroom_boulder', soil, rock, fractures, lower, side, upper, moss, gravel)
    return s3d.at(vignette, rz=90)

def bare_soil_patch(seed=0, width=4800, depth=4100, height=160, count=11):
    s3d.facets(4, smooth=False)
    rng = random.Random(seed)
    frames = s3d.ring(count, 1)
    points = []
    for f in frames:
        x, y = (f.origin.x, f.origin.y)
        scale = rng.uniform(0.9, 1)
        points.extend([(x * width / 2 * scale, y * depth / 2 * scale, height), (x * width / 2 * scale * 0.94, y * depth / 2 * scale * 0.94, 0)])
    soil = s3d.hull('bare_angular_soil', points)
    s3d.material(soil, 'soil', color=soil_colour, roughness=1)
    return soil

def soil_colour(x, y, z):
    patch = np.sin(x / 830 + y / 540) > 0.3
    return np.where(patch[..., None], np.array([0.29, 0.2, 0.15]), np.array([0.25, 0.17, 0.12]))

def mountain_boulder(seed=0, width=3300, depth=2780, height=2260, base=85):
    rng = random.Random(seed)
    outline = [(-0.48, -0.28), (-0.25, -0.5), (0.22, -0.49), (0.49, -0.25), (0.48, 0.22), (0.2, 0.47), (-0.25, 0.48), (-0.51, 0.17)]
    points = []
    for level, scale in [(0, 0.88), (0.4, 1), (0.77, 0.89), (1, 0.55)]:
        for x, y in outline:
            points.append((x * width * scale + rng.uniform(-80, 80), y * depth * scale + rng.uniform(-70, 70), base + height * level + rng.uniform(-85, 85)))
    core = s3d.hull('great_slate_boulder', points)
    fissure = s3d.hull('deep_diagonal_fissure', [(240, -1850, 330), (330, -1850, 330), (790, -1850, 2030), (680, -1850, 2030), (285, -950, 330), (735, -750, 2030)])
    core = s3d.cut(core, fissure)
    core = carve_sheltered_ledges(core, seed=seed + 12)
    s3d.material(core, 'rock', color=slate_colour, roughness=1)
    crown = s3d.at(crag_piece(seed=seed + 10), x=-420, y=220, z=height * 0.77)
    shoulder = s3d.at(crag_piece(seed=seed + 11, width=1000, depth=1300, height=1120), x=950, y=320, z=height * 0.43, rz=-18)
    return s3d.group('mountain_boulder', core, crown, shoulder)

def carve_sheltered_ledges(core, seed=0, width=940, opening=105, depth=185):
    rng = random.Random(seed)
    sites = shelf_fissure_sites()
    for probe, direction in sites:
        hits = s3d.snap(core, [s3d.Frame(probe)], direction=direction)
        if hits:
            w = width * rng.uniform(0.8, 1.1)
            cutter = s3d.hull('sheltered_angular_crack', [(-w / 2, -opening / 2, depth), (w / 2, -opening / 2, depth), (w / 2, opening / 2, depth), (-w / 2, opening / 2, depth), (-w / 2, 0, -depth), (w / 2, 0, -depth)])
            cutter = s3d.at(cutter, on=hits[0].turn(rz=rng.uniform(-8, 8)))
            core = s3d.cut(core, cutter)
    return core

def shelf_fissure_sites():
    return [((-890, -2600, 1050), '+Y'), ((-560, -2600, 1430), '+Y'), ((2600, -150, 1520), '-X')]

def slate_colour(x, y, z):
    patch = np.sin(x / 600 + z / 700) + np.cos(y / 640 - z / 850)
    return np.where((patch > 0.6)[..., None], np.array([0.43, 0.49, 0.52]), np.where((patch < -0.8)[..., None], np.array([0.27, 0.33, 0.37]), np.array([0.35, 0.405, 0.445])))

def crag_piece(seed=0, width=1540, depth=1450, height=680):
    rng = random.Random(seed)
    outline = [(-0.5, -0.24), (-0.21, -0.5), (0.36, -0.4), (0.5, 0.15), (0.12, 0.5), (-0.42, 0.36)]
    pts = []
    for z, scale, shift in [(0, 1, 0), (height * 0.75, 0.84, -width * 0.08), (height, 0.46, -width * 0.14)]:
        pts += [(x * width * scale + shift, y * depth * scale, z + rng.uniform(-height * 0.1, height * 0.1)) for x, y in outline]
    ob = s3d.hull('fractured_crown_block', pts)
    s3d.material(ob, 'rock', color=slate_colour, roughness=1)
    return ob

def exposed_fracture_planes(rock, seed=0, width=520, height=620, depth=65):
    hit = s3d.snap(rock, [s3d.Frame((610, -2400, 1130))], direction='+Y')[0]
    plate = s3d.hull('exposed_shear_flake', [(-width / 2, -height * 0.3, -depth), (width * 0.4, -height * 0.5, -depth), (width / 2, height * 0.22, -depth), (-width * 0.25, height * 0.5, -depth), (-width * 0.32, -height * 0.21, depth * 0.22), (width * 0.28, -height * 0.3, depth * 0.22), (width * 0.25, height * 0.2, depth * 0.22)])
    s3d.material(plate, 'rock', color='#889496', roughness=1)
    plate = s3d.at(plate, on=hit)
    return plate

def lower_mushroom_cluster(rock, seed=0):
    specs = [(-890, 1050, 1450, 365, 510, -0.3, -1), (-60, 770, 1100, 285, 450, 0.05, -1), (-1300, 630, 850, 250, 340, -0.55, -1), (-560, 1430, 980, 275, 390, -0.1, -1), (950, 1120, 1170, 290, 440, 0.55, -1)]
    return mushroom_population('lower_mushroom_cluster', rock, specs, 'front', seed)

def mushroom_population(name, rock, specs, side, seed):
    parts = []
    for i, (a, b, width, rise, reach, dx, dy) in enumerate(specs):
        probe = (a, -2700, b) if side == 'front' else (2700, a, b) if side == 'right' else (a, b, 3400)
        direction = '+Y' if side == 'front' else '-X' if side == 'right' else '-Z'
        hits = s3d.snap(rock, [s3d.Frame(probe)], direction=direction)
        if hits:
            site = s3d.Frame(tuple(hits[0].origin))
            mushroom = s3d.at(ledge_mushroom(width=width, rise=rise, reach=reach, dx=dx, dy=dy, seed=seed + 100 + i), on=site)
            parts.append(mushroom)
    return s3d.group(name, *parts)

def ledge_mushroom(seed=0, width=1100, rise=300, reach=400, dx=0, dy=-1, stem_d=145):
    end = (dx * reach, dy * reach, rise)
    stem = s3d.wire('short_crooked_stem', [(0, 0, -stem_d / 2), (end[0] * 0.45, end[1] * 0.45, rise * 0.6), end], d=[(0, stem_d * 0.83), (1, stem_d)])
    s3d.material(stem, 'rock', color='#c4b99a', roughness=0.95)
    cap = s3d.at(mushroom_cap(seed=seed + 1, width=width), x=end[0], y=end[1], z=end[2])
    return s3d.group('ledge_mushroom', stem, cap)

def mushroom_cap(seed=0, width=1100, depth_ratio=0.84, crown_ratio=0.13, rim_ratio=0.06, count=9):
    rng = random.Random(seed)
    rim = []
    for f in s3d.ring(count, 1):
        radial = rng.uniform(0.9, 1.06)
        rim.append((f.origin.x * width / 2 * radial, f.origin.y * width * depth_ratio / 2 * radial, rng.uniform(-0.015, 0.015) * width))
    upper = []
    for x, y, z in rim:
        upper.extend([(x, y, z), (x * 0.88, y * 0.88, z + width * rim_ratio), (x * 0.45 - width * 0.04, y * 0.45 + width * 0.03, width * crown_ratio)])
    upper.append((-width * 0.08, width * 0.04, width * (crown_ratio + 0.025)))
    cap = s3d.hull('thick_uneven_ochre_cap', upper)
    palette = ['#a96432', '#b67d38', '#975431', '#b78843']
    s3d.material(cap, 'rock', color=palette[rng.randrange(len(palette))], roughness=0.88)
    underside_pts = [(x * 0.995, y * 0.995, z - 1) for x, y, z in rim] + [(x * 0.99, y * 0.99, z - width * 0.055) for x, y, z in rim] + [(0, 0, -width * 0.14), (-width * 0.1, width * 0.1, -width * 0.12)]
    underside = s3d.hull('pale_polygonal_underside', underside_pts)
    s3d.material(underside, 'rock', color='#ded1ad', roughness=1)
    return s3d.group('broad_mushroom_cap', cap, underside)

def side_mushroom_cluster(rock, seed=0):
    specs = [(-150, 1520, 1250, 330, 430, 1, -0.15), (520, 1220, 940, 270, 350, 1, 0.05), (-590, 1130, 780, 250, 350, 1, -0.25)]
    return mushroom_population('side_mushroom_cluster', rock, specs, 'right', seed)

def upper_mushroom_cluster(rock, seed=0):
    specs = [(-700, 150, 1040, 300, 200, -0.2, -0.1), (40, 490, 730, 235, 150, 0.1, 0.1)]
    return mushroom_population('upper_mushroom_cluster', rock, specs, 'top', seed)

def crevice_moss(rock, seed=0, size=430, shelf_width=940):
    rng = random.Random(seed)
    sites = []
    for probe, direction in shelf_fissure_sites():
        for across in (-0.34, 0, 0.34):
            x, y, z = probe
            offset = across * shelf_width
            shifted = (x + offset, y, z) if direction == '+Y' else (x, y + offset, z)
            hits = s3d.snap(rock, [s3d.Frame(shifted)], direction=direction)
            if hits:
                sites.append(hits[0].offset(55))
    moss = []
    for i, site in enumerate(sites):
        patch = s3d.at(moss_cushion(seed=seed + 100 + i, width=size * rng.uniform(0.8, 1.2)), on=site)
        moss.append(patch)
    return s3d.group('selective_crevice_moss', *moss)

def moss_cushion(seed=0, width=270):
    rng = random.Random(seed)
    pts = []
    for f in s3d.ring(7, 1):
        r = rng.uniform(0.7, 1)
        pts.extend([(f.origin.x * width * r, f.origin.y * width * 0.52 * r, -80), (f.origin.x * width * 0.72 * r, f.origin.y * width * 0.4 * r, width * 0.24)])
    ob = s3d.hull('angular_olive_moss', pts)
    s3d.material(ob, 'moss', color=rng.choice(['#666b39', '#777846', '#555d34']), roughness=1)
    return ob

def scattered_angular_gravel(soil, rock, seed=0, count=26):
    rng = random.Random(seed)
    sites = s3d.scatter(count * 4, soil, seed=seed + 1)
    kept = [f for f in sites if f.origin.z > 150 and (f.origin.x / 1800) ** 2 + (f.origin.y / 1530) ** 2 > 1]
    pieces = []
    for i, f in enumerate(kept[:count]):
        stone = gravel_piece(seed=seed + 100 + i, width=rng.uniform(95, 280))
        pieces.append(s3d.at(stone, on=s3d.Frame(tuple(f.origin)), rz=rng.uniform(0, 360)))
    return s3d.group('scattered_angular_gravel', *pieces)

def gravel_piece(seed=0, width=180):
    rng = random.Random(seed)
    pts = [(-width / 2, -width * 0.25, -10), (width * 0.4, -width * 0.4, 0), (width * 0.5, width * 0.3, 0), (-width * 0.3, width * 0.4, 0), (-width * 0.15, 0, width * rng.uniform(0.3, 0.7)), (width * 0.15, width * 0.1, width * 0.32)]
    ob = s3d.hull('angular_slate_gravel', pts)
    s3d.material(ob, 'rock', color=rng.choice(['#565e60', '#747777', '#73675a']), roughness=1)
    return ob

import sand3d as s3d
import random

def violet(seed=0):
    s3d.facets(6, smooth=False)
    roots = root_foot(seed=seed + 1)
    stem = s3d.at(bent_stem(seed=seed + 2), on=roots.crown)
    foliage = s3d.at(basal_leaf_petioles(seed=seed + 3), on=roots.crown)
    end = stem.tip.origin
    stem_tip = s3d.local(stem, x=end.x, y=end.y, z=end.z)
    sepals = s3d.at(sepal_cup(seed=seed + 4), on=stem_tip)
    throat = sepals.flower.origin
    flower_frame = s3d.local(sepals, x=throat.x, y=throat.y, z=throat.z)
    upper = s3d.at(upper_petals(seed=seed + 5), on=flower_frame)
    sides = s3d.at(lateral_petals(seed=seed + 6), on=flower_frame)
    lip = s3d.at(lower_lip_petal(seed=seed + 7), on=flower_frame)
    center = s3d.at(yellow_center(seed=seed + 8), on=flower_frame)
    return s3d.at(s3d.assembly('solitary_violet', roots, stem, foliage, sepals, upper, sides, lip, center), rz=180)

def root_foot(seed, spread=18, height=8, count=6):
    crown = s3d.loft('root_crown', s3d.station(0, 9, 8), s3d.station(height / 2, 13, 11), s3d.station(height, 5, 5))
    s3d.material(crown, 'bark', color='#655943', roughness=0.95)
    lengths = s3d.vary(spread, 4, count, seed=seed + 1)
    sites = s3d.ring(count, 0).jitter(rz=12, seed=seed + 2)
    roots = [s3d.at(exposed_root(length=length, height=height, seed=seed + 10 + i), on=frame) for i, (length, frame) in enumerate(zip(lengths, sites))]
    return s3d.assembly('root_foot', crown, roots, crown=s3d.local(crown, z=height))

def exposed_root(length, height, seed, diameter=3.8):
    rng = random.Random(seed)
    path = [(0, 0, height * 0.65), (0, length * 0.45, diameter * 0.75), (rng.uniform(-2, 2), length, diameter * 0.31)]
    root = s3d.wire('exposed_root', path, d=[(0, diameter), (0.5, diameter * 0.7), (1, diameter * 0.35)])
    s3d.material(root, 'bark', color=rng.choice(['#706047', '#5f583d', '#78664c']), roughness=0.95)
    return root

def bent_stem(seed, height=145, diameter=3.1, lean=8):
    lean *= random.Random(seed).uniform(0.94, 1.06)
    path = s3d.spline([(0, 0, 0), (-2, 1, height * 0.32), (1, 5, height * 0.68), (lean, 5, height * 0.91), (lean, 0, height)])
    stem = s3d.wire('gently_bent_stem', path, d=[(0, diameter), (1, diameter * 0.73)])
    s3d.material(stem, 'leaf', color='#477347', roughness=0.82)
    end = s3d.along(path, count=2)[-1].origin
    return s3d.assembly('bent_stem', stem, tip=s3d.local(stem, x=end.x, y=end.y, z=end.z))

def basal_leaf_petioles(seed, count=4):
    sites = s3d.ring(count, 1, start=17).jitter(rz=13, seed=seed + 1)
    sizes = s3d.vary(1, 0.16, count, seed=seed + 2)
    leaves = [s3d.at(petiole_and_leaf(seed=seed + 10 + i), on=f, scale=v) for i, (f, v) in enumerate(zip(sites, sizes))]
    return s3d.group('basal_leaf_petioles', leaves)

def petiole_and_leaf(seed, reach=17, rise=14, diameter=1.8):
    rng = random.Random(seed)
    rise = rise * rng.uniform(0.8, 1.2)
    path = [(0, 0, 0), (0, reach * 0.5, rise * 0.7), (0, reach, rise)]
    petiole = s3d.wire('leaf_petiole', path, d=[(0, diameter), (1, diameter * 0.65)])
    s3d.material(petiole, 'leaf', color='#43673b', roughness=0.9)
    leaf_frame = s3d.Frame(path[-1], normal=(0, reach * 0.5, rise * 0.3), up=(0, 0, -1)).turn(rz=rng.uniform(-14, 14))
    leaf = s3d.at(heart_shaped_leaves(seed=seed + 1), on=leaf_frame)
    return s3d.group('petiole_and_leaf', petiole, leaf)

def heart_shaped_leaves(seed, width=33, length=34, fold=2.6, thickness=0.45):
    half_heart = [(0, 0), (-0.16, -0.13), (-0.36, -0.1), (-0.49, 0.06), (-0.48, 0.23), (-0.51, 0.32), (-0.39, 0.53), (-0.27, 0.68), (0, 1)]
    asymmetry = random.Random(seed).uniform(0.9, 1.05)
    outline = half_heart + [(-x * asymmetry, z) for x, z in reversed(half_heart[1:-1])]
    boundary = [(x * width, 0, z * length) for x, z in outline]
    ridge = (0, -fold, length * 0.39)
    palette = ['#315b3d', '#3c6c42', '#447b49', '#54854d']
    rng = random.Random(seed)
    panels = [polygon_panel([ridge, p, boundary[(i + 1) % len(boundary)]], thickness, rng.choice(palette), 'leaf') for i, p in enumerate(boundary)]
    vein = s3d.wire('leaf_midrib', [(0, -0.12, 0), (0, -fold - 0.15, length * 0.39), (0, -0.12, length)], d=0.48)
    s3d.material(vein, 'leaf', color='#7d9b56', roughness=0.92)
    return s3d.group('heart_shaped_leaf', panels, vein)

def polygon_panel(points, thickness, color, kind):
    back = [(x, y + thickness, z) for x, y, z in points]
    panel = s3d.hull('angular_plane', points + back)
    s3d.material(panel, kind, color=color, roughness=0.87)
    return panel

def sepal_cup(seed, reach=14, width=5, lift=6):
    neck = s3d.wire('green_receptacle', [(0, 0, 0), (0, -3, lift * 0.65), (0, -5, lift)], d=[(0, 2.5), (1, 6)])
    s3d.material(neck, 'leaf', color='#456a3d', roughness=0.9)
    frame = s3d.Frame((0, -4, lift), normal=(0, -1, 0.23), up=(0, 0, 1))
    sepals = s3d.at(sepal_blade(seed=seed + 1, width=width, length=reach), on=s3d.ring(5, 1.5, start=18, on=frame))
    return s3d.assembly('sepal_cup', neck, sepals, flower=s3d.local(neck, y=-5, z=lift))

def sepal_blade(seed, width, length):
    blade = s3d.loft('pointed_sepal', s3d.station(0, width * 0.4, 1.3), s3d.station(length * 0.45, width, 1.3, y=length * 0.1), s3d.station(length, 0, 0, y=length * 0.2), tip='sharp')
    s3d.material(blade, 'leaf', color=random.Random(seed).choice(['#3e633c', '#456c3e']), roughness=0.95)
    return s3d.group('sepal_blade', s3d.at(blade, rx=-90))

def upper_petals(seed, width=29, length=36):
    left = s3d.at(faceted_petal(seed=seed + 1, width=width, length=length, palette=['#7650ba', '#9165cf', '#a77cdb', '#875bbf']), y=1.4, ry=-26)
    right = s3d.at(faceted_petal(seed=seed + 2, width=width * 0.94, length=length * 1.04, palette=['#8660c6', '#a278db', '#9365ce', '#b089df']), y=1.8, ry=29)
    return s3d.group('upper_petals', left, right)

def faceted_petal(seed, width, length, palette, thickness=0.65, fold=4.3, throat=0.23):
    outline = [(0, 0), (-0.36, 0.18), (-0.48, 0.57), (-0.5, 0.8), (-0.29, 0.98), (-0.1, 1), (0, 0.94), (0.1, 1), (0.5, 0.77), (0.43, 0.5), (0.34, 0.16)]
    boundary = [(x * width, -fold * z * 0.5, z * length) for x, z in outline]
    ridge = (0, -fold, length * 0.52)
    triangles = [[ridge, p, boundary[(i + 1) % len(boundary)]] for i, p in enumerate(boundary)]
    rng = random.Random(seed)
    panels = []
    throats = []
    for tri in triangles:
        outer = clip_at_height(tri, length * throat, above=True)
        inner = clip_at_height(tri, length * throat, above=False)
        if len(outer) >= 3:
            panels.append(polygon_panel(outer, thickness, rng.choice(palette), 'leaf'))
        if len(inner) >= 3:
            throats.append(pale_throat(inner, thickness=thickness, seed=seed + 1))
    veins = emissive_inner_veins(triangles, width=width, length=length, seed=seed + 2)
    return s3d.group('fan_petal', panels, throats, veins)

def clip_at_height(points, height, above):
    result = []
    for p, q in zip(points, points[1:] + points[:1]):
        pin = p[2] >= height if above else p[2] <= height
        qin = q[2] >= height if above else q[2] <= height
        if pin:
            result.append(p)
        if pin != qin:
            t = (height - p[2]) / (q[2] - p[2])
            result.append(tuple((p[k] + t * (q[k] - p[k]) for k in range(3))))
    area = abs(sum((p[0] * q[2] - q[0] * p[2] for p, q in zip(result, result[1:] + result[:1]))))
    return result if area > 0.0001 else []

def pale_throat(points, thickness, seed):
    return polygon_panel(points, thickness, random.Random(seed).choice(['#e4d9ee', '#dfd4ed']), 'leaf')

def emissive_inner_veins(triangles, width, length, seed, diameter=0.38):
    strokes = []
    diameter *= random.Random(seed).uniform(0.92, 1.08)
    paths = [[(-0.03, 0.07), (-0.04, 0.18), (-0.11, 0.33), (-0.18, 0.48)], [(0.03, 0.07), (0.04, 0.19), (0.13, 0.34), (0.22, 0.45)], [(0, 0.11), (0, 0.26), (0.02, 0.43), (0.03, 0.56)], [(-0.11, 0.33), (-0.22, 0.36)], [(0.13, 0.34), (0.25, 0.36)]]
    for line in paths:
        path = [surface_point(triangles, x * width, z * length) for x, z in line]
        vein = s3d.wire('luminous_violet_vein', path, d=diameter)
        s3d.material(vein, 'plastic', color='#aa40f2', roughness=0.6, emission=4.2)
        strokes.append(vein)
    return s3d.group('emissive_inner_veins', strokes)

def surface_point(triangles, x, z, lift=0.22):
    for a, b, c in triangles:
        det = (b[2] - c[2]) * (a[0] - c[0]) + (c[0] - b[0]) * (a[2] - c[2])
        if abs(det) < 1e-06:
            continue
        u = ((b[2] - c[2]) * (x - c[0]) + (c[0] - b[0]) * (z - c[2])) / det
        v = ((c[2] - a[2]) * (x - c[0]) + (a[0] - c[0]) * (z - c[2])) / det
        if min(u, v, 1 - u - v) >= -1e-05:
            return (x, u * a[1] + v * b[1] + (1 - u - v) * c[1] - lift, z)
    raise ValueError('Vein leaves petal surface')

def lateral_petals(seed, width=34, length=37):
    left = s3d.at(faceted_petal(seed=seed + 1, width=width, length=length, palette=['#7041ac', '#8851c0', '#9b65d0', '#7946b3']), y=0, ry=-83)
    right = s3d.at(faceted_petal(seed=seed + 2, width=width * 0.96, length=length * 0.96, palette=['#8350bd', '#9860cf', '#ad79dc', '#7844b2']), y=-0.6, ry=82)
    return s3d.group('lateral_petals', left, right)

def lower_lip_petal(seed, width=46, length=36):
