def yellow_center(seed, width=6, height=5):
    core = s3d.at(s3d.loft('golden_eye', s3d.station(0, width * 0.8, 2), s3d.station(height * 0.5, width, 3), s3d.station(height, width * 0.55, 2)), y=-2.7, z=-height / 2)
