import sand3d as s3d
import numpy as np

def dark_river_cattail_vignette(seed=0):
    s3d.facets(4, smooth=False)
    sand = rippled_sand_patch(seed=seed + 1)
    river = river_strip(seed=seed + 2)
    plants = cattail_clump(sand, seed=seed + 3)
    return s3d.assembly('dark_river_cattail_vignette', sand, river, plants)

def rippled_sand_patch(seed=0, depth=850, height=48, ripple=10, wavelength=145, sample=34):
    edge = shoreline(depth)
    outline = [(-490, -depth / 2)] + edge + [(-440, 390), (-550, 190), (-520, -190)]
    sand = s3d.extrude('charcoal_rippled_sand', s3d.poly(outline), height)
    wave = s3d.waves(wavelength, direction=76, sharpness=0.35, phase=15)
    s3d.displace(sand, ripple, 65, noise=wave, faces='top', direction='+Z', step=sample)

    def sand_color(x, y, z):
        patch = s3d.noise(x / 240, y / 240, z / 240, seed=seed)
        return np.stack((0.22 + 0.025 * patch, 0.225 + 0.026 * patch, 0.215 + 0.025 * patch), axis=-1)
    s3d.material(sand, 'sand', color=sand_color, roughness=1)
    return sand

def shoreline(depth=850):
    return [(80, -depth / 2), (180, -320), (135, -130), (230, 80), (150, 270), (210, 370), (75, depth / 2)]

def river_strip(seed=0, depth=850, height=33):
    edge = shoreline(depth)
    outline = edge + [(465, depth / 2), (550, 290), (540, -270), (430, -depth / 2)]
    water = s3d.extrude('blue_black_river', s3d.poly(outline), height)

    def water_color(x, y, z):
        patch = s3d.noise(x / 300, y / 300, z / 300, seed=seed)
        return np.stack((0.055 + 0.008 * patch, 0.105 + 0.012 * patch, 0.135 + 0.016 * patch), axis=-1)
    s3d.material(water, 'plastic', color=water_color, roughness=0.3)
    return water

def cattail_clump(ground, seed=0, base_x=-120, base_y=0):
    stems = [(-85, 45, 1280, -42, 8, 285), (45, 55, 1055, 45, 14, 260), (8, -55, 1380, 28, -10, 270)]
    stalk_parts = []
    for i, (x, y, height, lean_x, lean_y, head_h) in enumerate(stems):
        hit = s3d.snap(ground, [(base_x + x, base_y + y, 100)], direction='-Z')[0]
        plant = s3d.at(cattail_stalk(seed=seed + 10 + i, height=height, lean_x=lean_x, lean_y=lean_y, head_h=head_h), on=s3d.Frame(hit.origin).offset(-3))
        stalk_parts.append(plant)
    leaf_specs = [(980, 57, 290, 185), (760, 64, 340, 255), (1080, 48, 205, 30), (860, 60, 330, 345), (680, 58, 295, 100), (1130, 44, 150, 220), (810, 58, 285, 285)]
    leaves = []
    for i, (height, width, lean, turn) in enumerate(leaf_specs):
        hit = s3d.snap(ground, [(base_x, base_y, 100)], direction='-Z')[0]
        leaf = s3d.at(blade_leaf(seed=seed + 30 + i, height=height, width=width, lean=lean), on=s3d.Frame(hit.origin).offset(-5).turn(rz=turn))
        leaves.append(leaf)
    return s3d.group('cattail_clump', stalk_parts, leaves)

def cattail_stalk(seed=0, height=1280, lean_x=-42, lean_y=8, head_h=285, diameter=14):
    path = [(0, 0, 0), (lean_x * 0.35, lean_y * 0.35, height * 0.55), (lean_x, lean_y, height)]
    stalk = s3d.wire('angular_olive_stalk', path, diameter, tip='flat')

    def stalk_color(x, y, z):
        patch = s3d.noise(x / 180, y / 180, z / 300, seed=seed)
        return np.stack((0.245 + 0.018 * patch, 0.275 + 0.02 * patch, 0.12 + 0.012 * patch), axis=-1)
    s3d.material(stalk, 'leaf', color=stalk_color, roughness=0.8)
    terminal = s3d.along(path, count=2)[-1]
    head = s3d.at(cattail_seed_head(seed=seed + 100, height=head_h), on=terminal.offset(-4))
    return s3d.group('stalk_with_seed_head', stalk, head)

def cattail_seed_head(seed=0, height=285, diameter=76, bevel=9):
    radius = diameter / 2
    profile = s3d.poly([(0, 0), (radius - bevel / 2, 0), (radius, bevel), (radius, height - bevel), (radius - bevel / 2, height), (0, height)])
    head = s3d.revolve('blunt_brown_seed_head', profile)

    def head_color(x, y, z):
        patch = s3d.noise(x / 90, y / 90, z / 160, seed=seed)
        return np.stack((0.235 + 0.025 * patch, 0.125 + 0.016 * patch, 0.072 + 0.01 * patch), axis=-1)
    s3d.material(head, 'velvet', color=head_color, roughness=1)
    return head

def blade_leaf(seed=0, height=980, width=57, lean=290, thickness=11):
    bend = s3d.vary(1, 0.12, 1, seed=seed)[0]
    leaf = s3d.loft('folded_pointed_blade', s3d.station(0, width * 0.24, thickness * 0.5), s3d.station(height * 0.22, width, thickness, x=lean * 0.08), s3d.station(height * 0.6, width * 0.85, thickness * 0.8, x=lean * 0.4), s3d.station(height * 0.86, width * 0.4, thickness * 0.45, x=lean * 0.75 * bend), s3d.station(height, 0, 0, x=lean * bend), tip='sharp')

    def leaf_color(x, y, z):
        patch = s3d.noise(x / 210, y / 210, z / 300, seed=seed + 1)
        return np.stack((0.235 + 0.026 * patch, 0.285 + 0.025 * patch, 0.125 + 0.014 * patch), axis=-1)
    s3d.material(leaf, 'leaf', color=leaf_color, roughness=0.85)
    return leaf

import sand3d as s3d
import numpy as np

def autumn_mushroom_cluster(seed=0):
    stump = weathered_stump(seed=seed + 1)
    recipes = [(tall_rear_stem, large_russet_cap, large_cap_gills, (-20, 17), (-4, -4, 8)), (right_stem, right_orange_cap, right_cap_gills, (25, 4), (2, 10, -12)), (front_left_stem, front_left_ochre_cap, front_left_gills, (-27, -20), (10, -13, 17)), (small_front_stem, small_front_russet_cap, small_front_gills, (29, -22), (19, 18, -8))]
    mushrooms = []
    for i, (stem_fn, cap_fn, gill_fn, xy, tilt) in enumerate(recipes):
        hit = s3d.snap(stump, [s3d.Frame((xy[0], xy[1], 250))], direction='-Z')[0]
        foot = s3d.Frame(tuple(hit.origin)).move(z=-1).turn(rx=tilt[0], ry=tilt[1], rz=tilt[2])
        stem = s3d.at(stem_fn(seed=seed + 100 * (i + 1)), on=foot)
        cap_tilts = [(-12, -14), (16, 12), (-10, -12), (8, 12)]
        tip = stem.face('end').turn(rx=cap_tilts[i][0], ry=cap_tilts[i][1])
        cap = s3d.at(cap_fn(seed=seed + 100 * (i + 1) + 1), on=tip)
        gills = s3d.at(gill_fn(seed=seed + 100 * (i + 1) + 2), on=tip)
        mushrooms.append(s3d.group('mushroom_' + str(i), stem, cap, gills))
    return s3d.at(s3d.assembly('autumn_mushroom_cluster', stump, mushrooms), rz=180)

def weathered_stump(seed=1, width=105, depth=91, height=63, wall=6, wood_height=57):
    s3d.facets(6, smooth=False)
    bark = s3d.loft('dark_bark', s3d.station(0, width * 0.91, depth * 0.91), s3d.station(height * 0.2, width, depth, x=-2), s3d.station(height * 0.72, width * 0.88, depth * 0.88, x=1), s3d.station(height, width * 0.94, depth * 0.94, x=-1))
    bark = s3d.shell(bark, wall, open='end')
    cuts = s3d.at(rim_notch(height=height), on=s3d.ring(3, width * 0.43, start=18))
    bark = s3d.cut(bark, cuts)
    s3d.material(bark, 'bark', color=patch_colour('#42271b', 0.19, seed), roughness=1)
    wood = s3d.loft('exposed_heartwood', s3d.station(0, width * 0.78, depth * 0.78), s3d.station(wood_height, width * 0.77, depth * 0.77, x=-1))
    fissure = s3d.at(wood_fissure(length=width * 0.65), z=wood_height - 11, rz=24)
    cross = s3d.at(wood_fissure(length=width * 0.42, width=2), x=10, y=3, z=wood_height - 11, rz=111)
    wood = s3d.cut(wood, fissure, cross)
    s3d.material(wood, 'walnut', color=patch_colour('#94603b', 0.13, seed + 1), roughness=1)
    rings = growth_rings(width=width * 0.77, depth=depth * 0.77, z=wood_height, seed=seed + 2)
    return s3d.group('weathered_stump', bark, wood, rings)

def rim_notch(height, width=13, reach=21, drop=19):
    return s3d.hull('broken_bark_notch', [(-reach / 2, -width / 2, height + 1), (reach / 2, -width / 2, height + 1), (-reach / 2, width / 2, height + 1), (reach / 2, width / 2, height + 1), (-reach / 2, 0, height - drop), (reach / 2, 0, height - drop)])

def patch_colour(hex_colour, contrast, seed):
    base = np.array([int(hex_colour[i:i + 2], 16) / 255 for i in (1, 3, 5)])
    phase = seed * 0.731

    def color(x, y, z):
        patch = np.sin(x * 0.071 + y * 0.047 + phase) * np.cos(z * 0.061 - y * 0.029 + phase * 0.7)
        return np.clip(base[None, :] * (1 + contrast * patch[:, None]), 0, 1)
    return color

def wood_fissure(length, width=3, depth=13):
    return s3d.hull('angular_wood_split', [(-length / 2, 0, depth), (length / 2, -width / 2, depth), (length / 2, width / 2, depth), (-length / 2 + width, 0, 0), (length / 2, 0, 0)])

def growth_rings(width, depth, z, seed):
    rings = []
    for k, ratio in enumerate((0.38, 0.69)):
        band = s3d.tube('angular_growth_ring', width * ratio, width * ratio - 0.8, 0.25)
        band = s3d.at(band, z=z + 0.03, scale=(1, depth / width, 1))
        s3d.material(band, 'walnut', color=patch_colour('#70462c', 0.1, seed + k), roughness=1)
        rings.append(band)
    return s3d.group('growth_rings', rings)

