    stem = s3d.loft(name, s3d.station(0, d, d * 0.91), s3d.station(h * 0.32, d * 0.88, d * 0.8, x=drift[0] * 0.2), s3d.station(h * 0.76, d * 0.67, d * 0.65, x=drift[0], y=drift[1]), s3d.station(h + 1, d * 0.77, d * 0.72, x=drift[0], y=drift[1]))
